insert into public.sistemas (nome, descricao, configuracao, criado_por)
select
  'World Trigger RPG',
  'RPG de Trion focado em estratégia, leitura, decisão, squads, radar e Rank Wars.',
  '{"versao":4,"tipo":"world_trigger","dados":["d6","d10"],"modulos":{"trion":{"ativo":true,"criacao":"1d10+2","multiplicador":5,"limiteAcao":5,"regeneracao":1,"eficienciaAte":2,"bonusEficiencia":1,"sobrecargaApartir":5,"penalidadeSobrecarga":-1},"triggers":{"ativo":true},"squads":{"ativo":true,"minMembros":3,"maxMembros":4},"radar":{"ativo":true},"visibilidade":{"ativo":true,"porSquad":true},"bagworm":{"ativo":true,"custoPorTurno":1},"chameleon":{"ativo":true,"custoPorTurno":2},"operador":{"ativo":true},"rankWars":{"ativo":true},"eventosDinamicos":{"ativo":true}},"arsenal":{"atacantes":[{"nome":"Kogetsu","categoria":"Atacante","custoBase":1,"tecnicas":[["Corte Reto",1,"Ataque direto. +1 no teste se for frontal."],["Tornado",2,"Corte em arco. Atinge múltiplos alvos próximos."],["Senkū",4,"Corte à distância. Ignora cobertura leve."],["Flash",3,"Avança rapidamente e ataca. Ganha prioridade na ação."]]},{"nome":"Scorpion","categoria":"Atacante","custoBase":1,"tecnicas":[["Morfia",1,"Altera a forma da lâmina livremente."],["Agulha",2,"Ataque perfurante. +1 contra defesa."],["Mantis",3,"Combina duas lâminas. +2 no dano."],["Armadura Viva",2,"Forma proteção temporária."]]},{"nome":"Raygust","categoria":"Atacante","custoBase":1,"tecnicas":[["Modo Escudo",1,"Reduz dano recebido em -2."],["Thruster",3,"Avanço explosivo."],["Âncora",2,"Não pode ser empurrado ou derrubado."],["Captura",3,"Prende o alvo temporariamente."]]}],"armeiros":[{"nome":"Asteroid","custo":"1 por disparo","efeito":"dano bruto puro"},{"nome":"Hound","custo":2,"efeito":"projéteis seguem o alvo"},{"nome":"Viper","custo":"2–3","efeito":"trajetória definida pelo jogador"},{"nome":"Meteor","custo":3,"efeito":"dano em área"}],"snipers":[{"nome":"Lightning","custo":2,"efeito":"tiro rápido, difícil de evitar"},{"nome":"Egret","custo":3,"efeito":"tiro equilibrado"},{"nome":"Ibis","custo":4,"efeito":"destruição massiva"}],"opcionais":[{"nome":"Shield","custo":"1–2","efeito":"Cria barreira de Trion"},{"nome":"Bagworm","custo":"1 por turno","efeito":"Remove usuário do radar"},{"nome":"Chameleon","custo":"2 por turno","efeito":"Invisibilidade total"},{"nome":"Spider","custo":2,"efeito":"Cria fios no cenário"},{"nome":"Lead Bullet","custo":3,"efeito":"Projétil não causa dano, mas pesa o alvo"},{"nome":"Thruster","custo":2,"efeito":"Impulso de movimento"},{"nome":"Bail Out","custo":"especial","efeito":"Retirada automática do combate"}]},"rankWars":{"composicao":"2–4 combatentes + 1 operador","squadsSimultaneos":"3–4","objetivo":"Pontuar melhor que os outros squads","pontuacao":{"abate":1,"ultimaEquipe":2,"assistencia":0.5,"controleArea":1,"execucaoTatica":1,"firstBlood":1,"eliminacaoLimpa":1},"ambientes":{"noite":"-1 percepção","neve":"reduz mobilidade","chuva":"reduz precisão","nevoa":"limita alcance"},"eventos":["Blackout","Colapso de área","Interferência"]},"atributos":[],"recursos":[{"id":"trion_atual","nome":"Trion Atual","sigla":"TRION","tipo":"numero","largura":1,"valor_maximo":1000,"ajuda":"Recurso de combate. Regenera 1 por turno."},{"id":"trion_maximo","nome":"Trion Máximo","sigla":"TRION MAX","tipo":"numero","largura":1,"calculado":true,"formula":"TRION_BASE * 5","ajuda":"Resultado inicial de Trion multiplicado por 5."},{"id":"trion_base","nome":"Resultado de Trion","sigla":"TRION BASE","tipo":"numero","largura":1,"ajuda":"Resultado de 1d10 + 2 usado para determinar o Trion."}],"pericias":[],"campos":[{"id":"squad","nome":"Squad","tipo":"texto","largura":1,"ajuda":"Equipe do agente."},{"id":"funcao","nome":"Função","tipo":"texto","largura":1,"placeholder":"Atacante, Artilheiro, Sniper, Operador..."},{"id":"estilo_squad","nome":"Estilo do Squad","tipo":"texto","largura":1,"placeholder":"Ofensiva, Defensiva, Tática, Móvel ou Híbrida"},{"id":"objetivo","nome":"Objetivo do personagem","tipo":"area","largura":2},{"id":"medo","nome":"Medo","tipo":"area","largura":2},{"id":"limite","nome":"Limite","tipo":"area","largura":2},{"id":"side_effect","nome":"Side Effect","tipo":"area","largura":2,"ajuda":"Vantagem especial do agente."},{"id":"side_effect_limitacao","nome":"Limitação do Side Effect","tipo":"area","largura":2,"ajuda":"Todo Side Effect deve possuir uma limitação obrigatória."},{"id":"triggers_equipados","nome":"Triggers equipados","tipo":"area","largura":2,"placeholder":"Liste os Triggers utilizados pelo agente."}],"secoes":[{"titulo":"Identidade do Agente","icone":"🧑‍✈️","colunas":2,"campos":["squad","funcao","estilo_squad"]},{"titulo":"Trion","icone":"🔋","colunas":3,"campos":["trion_base","trion_maximo","trion_atual"]},{"titulo":"Perfil","icone":"🎭","colunas":2,"campos":["objetivo","medo","limite","side_effect","side_effect_limitacao"]},{"titulo":"Arsenal","icone":"⚔️","colunas":1,"campos":["triggers_equipados"]}],"tema":{"corPrimaria":"#39b8ff","corFundo":"#071018","corPainel":"#0d1822"},"ficha":"ficha-generica.html"}'::jsonb,
  u.id
from auth.users u
where lower(coalesce(u.email,'')) = 'mestre@rpg.local'
  and not exists (select 1 from public.sistemas s where lower(s.nome) = lower('World Trigger RPG'));
